#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    int num_threads = 1;

    #pragma omp parallel
    {
        #pragma omp single
        {
            num_threads = omp_get_num_threads();
        }
    }

    std::vector<long long> block_sums(num_threads, 0);
    std::vector<long long> block_offsets(num_threads, 0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt = omp_get_num_threads();

        const std::size_t start = (n * static_cast<std::size_t>(tid)) / static_cast<std::size_t>(nt);
        const std::size_t end   = (n * static_cast<std::size_t>(tid + 1)) / static_cast<std::size_t>(nt);

        long long local_sum = 0;
        for (std::size_t i = start; i < end; ++i) {
            local_sum += x[i];
            output[i] = static_cast<int>(local_sum);
        }
        block_sums[tid] = local_sum;

        #pragma omp barrier

        #pragma omp single
        {
            long long offset = 0;
            for (int t = 0; t < nt; ++t) {
                block_offsets[t] = offset;
                offset += block_sums[t];
            }
        }

        const long long add = block_offsets[tid];
        for (std::size_t i = start; i < end; ++i) {
            output[i] = static_cast<int>(output[i] + add);
        }
    }
}
